test_that("canonical filenames parse", { expect_equal(format_daily_filename("mintemp", as.Date("2026-07-27")), "mintemp_2026-07-27.tif"); x<-parse_grid_filename("mintemp_2026-W53_est.tif","mintemp"); expect_true(x$valid); expect_true(x$estimated); expect_equal(x$iso_week,53) })
test_that("estimates do not affect observed coverage", { td<-tempdir(); dir.create(td,showWarnings=FALSE); file.create(file.path(td,"mintemp_2026-01-01_est.tif")); i<-inventory_grid_directory(td,"mintemp","daily"); expect_true(is.na(summarize_grid_inventory(i)$latest_observed)) })
test_that("requests contain valid requested days", { cfg<-list(cds=list(dataset_short_name="derived-era5-single-levels-daily-statistics",product_type="reanalysis",variable="2m_temperature",daily_statistic="daily_minimum",time_zone="utc+00:00",frequency="6_hourly",data_format="netcdf",download_format="unarchived")); x<-build_era5_mintemp_requests(as.Date(c("2024-02-28","2024-02-29")),c(40,-125,-1,-34),cfg); expect_equal(x[[1]]$day,c("28","29")); expect_true(validate_cds_request_structure(x[[1]])); expect_false("user"%in%names(x[[1]])) })
